/* -------------------------------------------- */
/*  Hazard Tests                                */
/* -------------------------------------------- */

/**
 * Enrich a hazard test with the format [[/hazard {level} {...tags}]]
 * @param {RegExpMatchArray} matchArray
 */
function enrichHazard([_match, terms, name]) {
  const [danger, ...tags] = terms.split(" ");

  // Build a temporary Action that resolves tags into hazard attributes
  const action = crucible.api.models.CrucibleAction.createHazard({danger: Number(danger), tags});
  action.prepare();
  const {damageType, defenseType, resource, restoration} = action.usage;

  // Prepare label
  const hazardRank = _loc("HAZARD.Rank", {danger});
  const parenthetical = name ? [hazardRank] : [];
  for ( const t of tags ) {
    const cfg = SYSTEM.ACTION.TAGS[t];
    if ( cfg && cfg.label && !cfg.internal ) parenthetical.push(_loc(cfg.label));
  }
  let label = name || hazardRank;
  const listFormatter = new Intl.ListFormat(game.i18n.lang, {style: "short", type: "unit"});
  if ( parenthetical.length ) label = _loc("HAZARD.Parenthetical", {label, tags: listFormatter.format(parenthetical)});
  // Prepare tooltip
  const defenseLabel = _loc(SYSTEM.DEFENSES[defenseType]?.label);
  const resourceLabel = _loc(SYSTEM.RESOURCES[resource]?.label);
  const damageLabel = _loc(SYSTEM.DAMAGE_TYPES[damageType]?.label) || "";
  const tooltip = restoration
    ? _loc("HAZARD.TooltipRestoration", {rank: hazardRank, defense: defenseLabel, resource: resourceLabel})
    : _loc("HAZARD.TooltipDamage", {rank: hazardRank, defense: defenseLabel, damage: damageLabel, resource: resourceLabel});

  // Return the enriched content tag
  const tag = document.createElement("enriched-content");
  tag.classList.add("hazard-check");
  Object.assign(tag.dataset, {danger, tags, defenseType, resource, tooltip});
  if ( damageType ) tag.dataset.damageType = damageType;
  if ( name ) tag.dataset.hazardName = name;
  tag.innerHTML = label;
  return tag;
}

/* -------------------------------------------- */

/**
 * Add interactivity to a rendered hazard enrichment.
 * @param {HTMLElement} element
 */
function renderHazard(element) {
  element.addEventListener("click", onClickHazard);
}

/* -------------------------------------------- */

/**
 * Handle a click on a hazard enriched element, executing the hazard check action for the actor.
 * @param {Event} event
 */
async function onClickHazard(event) {
  event.preventDefault();
  if ( !game.user.isGM ) return;
  const {danger, tags, damageType, defenseType, resource, hazardName} = event.target.dataset;
  return crucible.api.dice.HazardDialog.prompt({
    danger: Number(danger),
    tags: tags ? tags.split(",") : [],
    damageType: damageType || "void",
    defenseType: defenseType || "physical",
    resource: resource || undefined,
    name: hazardName || event.target.innerText
  });
}

